ALTER TABLE home_blocks ADD COLUMN config jsonb NOT NULL DEFAULT '{}';
UPDATE home_blocks SET type='upcoming' WHERE type='deals';
INSERT INTO home_blocks(type,title,position) SELECT 'banner','Featured promotions',0 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='banner');
UPDATE home_blocks SET title='Featured promotions',position=0,config='{"endpoint": "/home/banners", "show_all": "", "tooltip": "", "tooltip_lt": "", "title_lt": "Reklaminiai pasiūlymai", "kind": "banner"}'::jsonb WHERE type='banner';
INSERT INTO home_blocks(type,title,position) SELECT 'categories','Product categories',1 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='categories');
UPDATE home_blocks SET title='Product categories',position=1,config='{"endpoint": "/home/categories", "show_all": "", "tooltip": "", "tooltip_lt": "", "title_lt": "Prekių kategorijos", "kind": "categories"}'::jsonb WHERE type='categories';
INSERT INTO home_blocks(type,title,position) SELECT 'recent','Recently viewed',2 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='recent');
UPDATE home_blocks SET title='Recently viewed',position=2,config='{"endpoint": "/home/recently-viewed", "show_all": "", "tooltip": "Products you recently viewed.", "tooltip_lt": "Prekės, kurias neseniai peržiūrėjai.", "title_lt": "Neseniai peržiūrėta", "kind": "recent"}'::jsonb WHERE type='recent';
INSERT INTO home_blocks(type,title,position) SELECT 'recommended','Recommended for you',3 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='recommended');
UPDATE home_blocks SET title='Recommended for you',position=3,config='{"endpoint": "/home/recommended", "show_all": "/store?sort=popular", "tooltip": "Recommendations are based on user activity, including product ratings, cart additions, wishlist additions, and purchases. When you are signed in, recommendations are personalized; otherwise, they are based on data from users in the same country.", "tooltip_lt": "Rekomendacijos grindžiamos naudotojų veiklos duomenimis, įskaitant prekių įvertinimus, krepšelio papildymus, norų sąrašo papildymus ir pirkimus. Kai esi prisijungęs, rekomendacijos yra suasmenintos, kitu atveju jos grindžiamos tos pačios šalies naudotojų duomenimis.", "title_lt": "Rekomenduojama tau", "kind": "recommended"}'::jsonb WHERE type='recommended';
INSERT INTO home_blocks(type,title,position) SELECT 'best_sellers','Top games',4 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='best_sellers');
UPDATE home_blocks SET title='Top games',position=4,config='{"endpoint": "/home/best-sellers", "show_all": "/store?type=games&sort=popular", "tooltip": "Recommendations based on the products most frequently purchased by our users.", "tooltip_lt": "Rekomendacijos, pagrįstos dažniausiai mūsų vartotojų pirktais produktais", "title_lt": "Populiariausi žaidimai", "kind": "best"}'::jsonb WHERE type='best_sellers';
INSERT INTO home_blocks(type,title,position) SELECT 'egift_cards','Best selling eGift Cards',5 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='egift_cards');
UPDATE home_blocks SET title='Best selling eGift Cards',position=5,config='{"endpoint": "/home/gift-brands", "show_all": "/store?type=egift-cards&sort=popular", "tooltip": "Recommendations based on the products most frequently purchased by our users.", "tooltip_lt": "Rekomendacijos, pagrįstos dažniausiai mūsų vartotojų pirktais produktais", "title_lt": "Perkamiausios el. dovanų kortelės", "kind": "brands"}'::jsonb WHERE type='egift_cards';
INSERT INTO home_blocks(type,title,position) SELECT 'gift_cards','Best selling gift cards',6 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='gift_cards');
UPDATE home_blocks SET title='Best selling gift cards',position=6,config='{"endpoint": "/home/gift-cards", "show_all": "/store?category=gaming-ecards&sort=popular", "tooltip": "Recommendations based on the products most frequently purchased by our users.", "tooltip_lt": "Rekomendacijos, pagrįstos dažniausiai mūsų vartotojų pirktais produktais", "title_lt": "Populiariausi papildymai", "kind": "gifts"}'::jsonb WHERE type='gift_cards';
INSERT INTO home_blocks(type,title,position) SELECT 'upcoming','Upcoming games',7 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='upcoming');
UPDATE home_blocks SET title='Upcoming games',position=7,config='{"endpoint": "/home/upcoming", "show_all": "/store?category=pre-orders&sort=popular", "tooltip": "Products available to pre-order, selected by relevance.", "tooltip_lt": "Produktai, kuriuos galima užsisakyti iš anksto, parinkti pagal svarbą", "title_lt": "Įsigyk iš anksto", "kind": "upcoming"}'::jsonb WHERE type='upcoming';
INSERT INTO home_blocks(type,title,position) SELECT 'genres','Categories',8 WHERE NOT EXISTS(SELECT 1 FROM home_blocks WHERE type='genres');
UPDATE home_blocks SET title='Categories',position=8,config='{"endpoint": "/home/genres", "show_all": "", "tooltip": "", "tooltip_lt": "", "title_lt": "Kategorijos", "kind": "genres"}'::jsonb WHERE type='genres';
