CREATE TABLE home_genres(position integer PRIMARY KEY,label text NOT NULL,icon text NOT NULL);
INSERT INTO home_genres VALUES (1,'Action','action'),(2,'Adventure','adventure'),(3,'Simulation','simulation'),(4,'Strategy','strategy'),(5,'Indie','indie'),(6,'RPG','rpg'),(7,'FPS / TPS','fps'),(8,'Sport','sport'),(9,'Puzzle','puzzle'),(10,'Racing','racing'),(11,'Platform','platform'),(12,'Fighting','fighting'),(13,'Hack & Slash','hack-slash'),(14,'Arcade','arcade'),(15,'Point & Click','point-click'),(16,'MMO','mmo'),(17,'Music','music'),(18,'Educational','educational');
UPDATE home_product_groups SET position=CASE (SELECT slug FROM products WHERE id=product_id) WHEN 'grand-theft-auto-vi-xbox' THEN 0 WHEN 'grand-theft-auto-vi-ps5' THEN 1 WHEN 'psn-card-100-gbp' THEN 2 WHEN 'psn-card-100-usd' THEN 3 ELSE 4 END WHERE group_slug='recommended';
